INSERT INTO subtopics (id, general_topic_id, title, short_summary, long_summary, keywords, volume, public_position) VALUES
  ('a1000000-0000-4000-8000-000000000001', '8c4a1a64-d3b6-4eb2-b86c-d9af397cdb1e',
   'Redistricting Battles Heat Up',
   'Several states face court challenges over newly drawn congressional maps.',
   'Courts in multiple states are weighing whether newly drawn congressional maps comply with voting-rights protections. Plaintiffs argue the maps dilute certain communities'' votes, while state legislatures maintain the lines follow traditional districting principles. Rulings expected this term could shift several seats before the next election.',
   ARRAY['redistricting','gerrymandering','courts'], 12400, 0.48),
  ('a1000000-0000-4000-8000-000000000002', '8c4a1a64-d3b6-4eb2-b86c-d9af397cdb1e',
   'Election Security Funding Debate',
   'Lawmakers spar over how much federal money should support state election systems.',
   'A proposed appropriations package includes new grants for state election infrastructure — paper-ballot backups, audit programs, and cybersecurity staff. Supporters call it basic hygiene for democracy; opponents say elections are a state responsibility and warn against federal strings attached to the money.',
   ARRAY['elections','security','funding'], 8900, 0.52),
  ('a2000000-0000-4000-8000-000000000001', 'b2341048-0108-450d-91ae-d0f509f6f574',
   'Defense Budget Priorities',
   'The annual defense bill pits modernization against readiness spending.',
   'This year''s defense authorization debate centers on whether to prioritize next-generation systems — AI, drones, shipbuilding — or near-term readiness like maintenance and training. Allies watch closely as commitments abroad factor into the topline number.',
   ARRAY['defense','budget','military'], 10200, 0.55),
  ('a2000000-0000-4000-8000-000000000002', 'b2341048-0108-450d-91ae-d0f509f6f574',
   'Trade Talks With Pacific Partners',
   'Negotiators work toward a framework agreement on tariffs and supply chains.',
   'Trade representatives are negotiating a framework covering tariffs, digital trade, and critical-mineral supply chains with Pacific partners. Manufacturers want tariff relief; labor groups warn against repeating past agreements they say cost domestic jobs.',
   ARRAY['trade','tariffs','pacific'], 6100, 0.44),
  ('a3000000-0000-4000-8000-000000000001', 'f289ef45-488d-46cf-aad2-d045453f4875',
   'Inflation and the Fed''s Next Move',
   'Markets split on whether the central bank cuts rates this quarter.',
   'Inflation has cooled from its peak but remains above target, leaving the Federal Reserve weighing rate cuts against the risk of reigniting price growth. Housing costs and services inflation remain sticky, while goods prices have largely normalized.',
   ARRAY['inflation','fed','rates'], 15800, 0.5),
  ('a3000000-0000-4000-8000-000000000002', 'f289ef45-488d-46cf-aad2-d045453f4875',
   'Minimum Wage Ballot Measures',
   'Voters in several states will decide on wage increases this fall.',
   'Ballot measures to raise state minimum wages — some to $17/hour phased over several years — have qualified in multiple states. Small-business coalitions argue the increases accelerate automation; labor advocates point to studies showing limited employment effects.',
   ARRAY['wages','labor','ballot'], 7300, 0.58),
  ('a4000000-0000-4000-8000-000000000001', '49abf187-8b6b-419d-a093-a76dc7104819',
   'AI Regulation Takes Shape',
   'Lawmakers debate licensing, liability, and transparency rules for AI systems.',
   'Draft AI legislation proposes transparency requirements for training data, liability rules for AI-caused harms, and safety evaluations for frontier models. Startups warn of compliance burdens that favor incumbents; consumer groups say the rules don''t go far enough.',
   ARRAY['ai','regulation','tech policy'], 13500, 0.47),
  ('a4000000-0000-4000-8000-000000000002', '49abf187-8b6b-419d-a093-a76dc7104819',
   'Social Media Age Verification',
   'New state laws requiring age checks face First Amendment challenges.',
   'Several states now require platforms to verify users'' ages and obtain parental consent for minors. Civil-liberties groups have sued, arguing the laws burden adults'' anonymous speech; supporters cite youth mental-health data.',
   ARRAY['social media','minors','privacy'], 9100, 0.53),
  ('a5000000-0000-4000-8000-000000000001', 'd2cfb810-94f0-4446-982c-38ad27585bca',
   'Border Processing Rule Changes',
   'New asylum processing rules draw lawsuits from both directions.',
   'Updated rules speed initial asylum screenings and expand expedited removal. Immigration advocates say the timeline prevents fair hearings; border-state officials argue the changes don''t address visa overstays or fentanyl interdiction.',
   ARRAY['border','asylum','immigration'], 11800, 0.45),
  ('a5000000-0000-4000-8000-000000000002', 'd2cfb810-94f0-4446-982c-38ad27585bca',
   'Work Visa Backlog Reform',
   'Employers push for changes to employment-based green card caps.',
   'A bipartisan bill would recapture unused green card numbers and exempt advanced STEM degree holders from country caps. Tech employers back it strongly; opponents argue it undercuts wages for domestic graduates.',
   ARRAY['visas','green cards','employment'], 5400, 0.51),
  ('a6000000-0000-4000-8000-000000000001', '2e6042ef-4598-42a8-8624-1eb961845cbd',
   'Drug Price Negotiation Expansion',
   'Medicare negotiation may extend to more medications next year.',
   'The government is set to announce the next round of drugs subject to Medicare price negotiation. Pharmaceutical companies warn reduced revenue will cut R&D pipelines; patient groups counter that list prices have far outpaced inflation.',
   ARRAY['medicare','drug prices','health'], 8700, 0.6),
  ('a6000000-0000-4000-8000-000000000002', '2e6042ef-4598-42a8-8624-1eb961845cbd',
   'Grid Upgrades vs. Permitting Delays',
   'Clean energy projects stall in interconnection queues nationwide.',
   'Hundreds of gigawatts of wind, solar, and battery projects sit in grid-connection queues, some waiting five years. A permitting-reform package would set deadlines and expand transmission — but bundles in fossil-fuel provisions that split the coalition.',
   ARRAY['energy','grid','permitting'], 6800, 0.49),
  ('a7000000-0000-4000-8000-000000000001', '95f37b29-a5f9-432b-a411-b5ba1e16a493',
   'State Privacy Law Patchwork',
   'A dozen new state privacy laws take effect with differing requirements.',
   'With no federal privacy law, states continue passing their own — each with different consent rules, opt-out mechanisms, and enforcement. Businesses call for federal preemption; privacy advocates worry a federal floor would weaken stronger state protections.',
   ARRAY['privacy','data','regulation'], 4900, 0.46),
  ('a7000000-0000-4000-8000-000000000002', '95f37b29-a5f9-432b-a411-b5ba1e16a493',
   'Campus Speech Policies Under Review',
   'Universities revise demonstration rules amid free-expression lawsuits.',
   'Universities are rewriting protest and speaker policies after a year of high-profile clashes. Some adopt institutional-neutrality statements; others tighten time-place-manner rules. Litigation is testing where campus order ends and viewpoint discrimination begins.',
   ARRAY['speech','campus','first amendment'], 5600, 0.5)
ON CONFLICT (id) DO NOTHING;

